namespace Infrastructure.Service;

public class DeepSeekSettings
{
    public string ApiKey { get; set; } = "";
    public string ApiUri { get; set; } = "";

    public static string Prompt {
        get
        {
            // Persian prompt instructing DeepSeek how to extract products correctly
            var prompt = "@\"شما یک آرایه JSON از شیٔ کانال‌ها دریافت خواهید کرد. هر شیٔ کانال شامل فیلدهای:\r\n- channel_id (رشته)\r\n- status (رشته)\r\n- description (رشته)\r\n- messages (آرایه پیام‌ها)\r\n\r\nهر پیام شامل فیلدهای:\r\n- message_id (رشته)\r\n- datetime_utc (رشته ISO)\r\n- text (رشته یا null)\r\n- caption (رشته یا null)\r\n\r\nهدف: برای هر پیامِ مرتبط با معرفی یا فروش یک کالا، یک شیٔ محصول استخراج کنید با فیلدهای زیر (اگر مقدار مشخص نیست null قرار دهید):\r\n- ProductName: نام محصول یا عنوان کوتاه (رشته)\r\n- Title: تیتر یا اولین خط معنادار پیام (رشته)\r\n- ChannelId: مقدار channel_id کانال (رشته)\r\n- ChannelUserName: نام کاربری/شناسه کانال در صورت وجود (رشته)\r\n- ChannelDescription: متن description کانال (رشته)\r\n- ChannelCity: در صورت امکان شهر مرتبط از متن کانال یا پیام (رشته یا null)\r\n- ChannelPhoneNumbers: همه شماره تلفن‌های یافت‌شده در توضیحات کانال یا پیام، که با کاما جدا شده‌اند (رشته یا null)\r\n- CategoryName: دسته‌بندی محصول به فارسی (مثال: \"آچار آلن\", \"قیچی\", \"جعبه بکس\"). اگر از نام محصول قابل تشخیص نبود مقدار \"General\" را قرار دهید.\r\n- Price: عددی بر حسب تومان (عدد یا null). قوانین نرمال‌سازی قیمت در زیر شرح داده شده است.\r\n- Currency: رشته واحد نهایی (مثلاً \"تومان\"); پس از تبدیل مقدار Price این مقدار باید نشان داده شود.\r\n- Description: متن کامل پیام برای استفاده به عنوان توضیحات (رشته)\r\n- Brand: برند در صورت وجود (رشته یا null)\r\n- SellMethod: روش فروش در صورت ذکر (مثلاً \"کارتنی\", \"تکی\", \"تماس برای قیمت\") (رشته یا null)\r\n- MessageDate: مقدار datetime_utc پیام (رشته)\r\n\r\nقواعد مهم و نکات پیاده‌سازی (بخوان و دقیق اجرا کن):\r\n1) خروجی باید صرفاً یک آرایه JSON از اشیاء محصول باشد. هیچ متن توضیحی، مارک‌داون یا کامنتی اضافه نکن. فقط JSON خالص.\r\n2) حذف مقادیر نامشخص: برای هر فیلد که مقدار قابل استخراج وجود ندارد، مقدار null بنویس.\r\n3) قیمت‌ها (Price): خروجی عددی بر حسب تومان باشد (بدون جداکننده یا علامت واحد). قوانین تبدیل:\r\n   - اگر قیمت به صورت عدد کوتاه نوشته شده باشد مانند \"499\" یا \"۴۹۹\" یا \"۴۹۹-\" یا \"قیمت: 499\"، تفسیر کن که این مقدار به هزار تومان مربوط است و آن را در تومان ضرب در 1000 کن => 499000.\r\n   - اگر عبارت «هزار» یا «هزار تومان» یا «k» کنار عدد یا بعد آن آمده باشد (مثلاً \"499 هزار\" یا \"499هزار\" یا \"۴۹۹ هزار\"), عدد را در 1000 ضرب کن.\r\n   - اگر قیمت به صورت ریال نوشته شده باشد (کلمه «ریال» یا نماد) مقدار را بر 10 تقسیم کن تا به تومان تبدیل شود (مثلاً 4990000 ریال => 499000 تومان).\r\n   - اگر عدد دارای جداکننده‌های هزار (کاما، اسلش، نقطه یا فاصله) است، همه کاراکترهای غیر عددی را پاک کن و سپس اعمال تبدیل‌های فوق را اجرا کن.\r\n   - اگر متن صریحاً واحد دیگری مانند USD وجود دارد، مقدار را نگهدار و Currency آن واحد را بنویس ولی مقدار Price را در صورت امکان به تومان تبدیل کن؛ در غیر این صورت null قرار بده.\r\n4) تشخیص تبلیغات/آگهی‌ها: بعضی پیام‌ها صرفاً اطلاع‌رسانی یا تبلیغ عمومی هستند و محصول مشخص و قابل استخراج ندارند. اگر پیام حاوی مشخصات محصول (نام محصول، کد محصول، مشخصات فنی، قیمت، موجودی یا جزئیات بسته‌بندی) نبود یا فقط پیام عمومی بود، آن پیام را نادیده بگیر (هیچ شیٔ محصولی تولید نکن).\r\n5) استخراج دسته‌بندی (CategoryName): برای هر محصول از نام محصول و متن پیام استفاده کن تا دسته‌بندی دقیق را تعیین کنی. نمونه‌های پرکاربرد (جور کردن بر اساس کلیدواژه‌ها):\r\n   - اگر نام یا متن شامل \"آلن\" یا \"الن\" یا \"Allen\" یا \"آچار آلن\" باشد => \"آچار آلن\".\r\n   - اگر شامل \"قیچی\" یا \"قیچی باغبانی\" یا \"قیچی ورق\" باشد => \"قیچی\".\r\n   - اگر شامل \"جعبه بکس\" یا \"بکس\" یا \"بکس 1/4\" باشد => \"جعبه بکس\".\r\n   - اگر شامل \"پیچ گوشتی\" یا \"پیچگوشتی\" یا \"سر پیچ\" باشد => \"پیچ‌گوشتی\".\r\n   - اگر شامل \"انبر\" یا \"انبردست\" باشد => \"انبر\".\r\n   - اگر شامل نام‌های عمومی ابزار (\"فازمتر\", \"منگنه\", \"پمپ\", \"ترکمتر\") باشد به همان نام دسته بده.\r\n   - اگر هیچ کلمه کلیدی مشخصی پیدا نشد، مقدار \"General\" قرار بده.\r\n6) شماره تلفن‌ها (ChannelPhoneNumbers): شماره‌ها را از فیلد description کانال و همچنین متن پیام‌ها جستجو کن. شماره‌ها ممکن است با پیش‌شماره +98 یا 0 یا بدون فاصله نوشته شوند. همه شماره‌های یافت‌شده را یک‌بار استخراج کن، پاک‌سازی کن (فقط ارقام و پیش‌شماره +98) و سپس با کاما جداسازی کن و در فیلد ChannelPhoneNumbers قرار بده. اگر هیچ شماره‌ای نبود مقدار null بنویس.\r\n7) نام شهر (ChannelCity): اگر در description کانال نام شهر واضحی دیدی استخراج کن، در غیر این صورت null بنویس.\r\n8) خروجی نمونه (فقط برای الگو):\r\n[ { \"ProductName\": \"قیچی PVC بر اتوماتیک هامبورگ\", \"Title\": \"قیچی PVCبر اتوماتیک هامبورگ\", \"ChannelId\": \"hamburgtools\", \"ChannelUserName\": \"hamburgtools\", \"ChannelDescription\": \"کانال رسمی ابزارآلات هامبورگ در روبیکا\", \"ChannelCity\": null, \"ChannelPhoneNumbers\": null, \"CategoryName\": \"قیچی\", \"Price\": null, \"Currency\": null, \"Description\": \"📎قیچی PVCبر اتوماتیک هامبورگ\\n\\n🔸کد محصول: H5906\\n  🔸تیغه فولاد ضد زنگ SK5\\n🔸مکانیزم اتوماتیک\\n\\n🔹️هامبورگ، ابزار همیشگی...\", \"Brand\": \"هامبورگ\", \"SellMethod\": null, \"MessageDate\": \"2026-08-01T07:15:52+00:00\" } ]\r\n\r\nدوباره تأکید می‌کنم: فقط یک آرایه JSON برگردان. هیچ متن اضافه یا توضیحی خارج از JSON اجازه ندارم.\";";
            return prompt;
        }
    }
